#!/bin/sh
# cargo-loco-generate/cargo-loco-generate.sh
#
# Generator script for Loco scaffolding.
#
# Run from inside a fresh Loco project (one created via
# `loco new --name <form-slug> --db postgres --bg async --assets serverside`)
# to scaffold every CRUD resource for this form. Tables are scaffolded in the
# same order as the form's sql-migrations/ so that FK targets already exist
# when referencing tables are created.
#
# Generated by bin/generate-cargo-loco-scaffold.py from sql-migrations/*.sql.
# Do not edit by hand — re-run the generator after changing the SQL migrations.

set -euf


echo "Scaffolding outpatient-outcome-report (6 tables)..."

cargo loco generate scaffold patient \
    deleted_at:ts \
    name:string! \
    birth_date:date \
    united_kingdom_nhs_number:string^ \
    waist_as_cm:double \
    height_as_cm:double \
    weight_as_kg:double \
    body_mass_index:double \
    waist_height_ratio:double \
    vo2_max:double \
    --htmx && \
cargo loco generate scaffold clinician \
    deleted_at:ts \
    name:text! \
    role:text! \
    registration_body:text! \
    registration_number:text! \
    united_kingdom_nhs_number:string^ \
    --htmx && \
cargo loco generate scaffold assessment \
    patient:references \
    status:string! \
    clinic_date:date \
    specialty:string! \
    clinician:references \
    modality:string! \
    appointment_type:string! \
    referral_date:date \
    appointment_date:date \
    wait_time_days:int \
    service_target_days:int \
    nhs_attendance_outcome:string! \
    presenting_complaint:text! \
    diagnosis:text! \
    treatment_delivered:text! \
    outcome_classification:string! \
    global_rating_of_change:int \
    self_rated_health:string! \
    fft_response:string! \
    fft_comment:text! \
    disposition:string! \
    next_appointment_date:date \
    onward_referral_specialty:string! \
    followup_notes:text! \
    reporting_clinician:references \
    reporting_clinician_name:string! \
    reporting_clinician_role:string! \
    signed_off_at:ts \
    --htmx && \
cargo loco generate scaffold grading_result \
    assessment:references \
    overall_grade:string! \
    clinical_grade:string! \
    prom_grade:string! \
    prem_grade:string! \
    operational_grade:string! \
    result_notes:text! \
    graded_at:ts! \
    --htmx && \
cargo loco generate scaffold grading_fired_rule \
    grading_result:references \
    rule_id:string! \
    category:string! \
    description:text! \
    severity_level:string! \
    --htmx && \
cargo loco generate scaffold grading_additional_flag \
    grading_result:references \
    flag_id:string! \
    category:string! \
    description:text! \
    priority:string! \
    --htmx

echo "Done."
